import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds exact half-cents to the even cent so ties don't inflate invoices", () => {
    expect(roundCents(0.5)).toBe(0);
    expect(roundCents(1.5)).toBe(2);
    expect(roundCents(2.5)).toBe(2);
    expect(roundCents(3.5)).toBe(4);
  });

  it("rounds non-tie amounts to the nearest cent", () => {
    expect(roundCents(12.49)).toBe(12);
    expect(roundCents(12.51)).toBe(13);
    expect(roundCents(7)).toBe(7);
  });

  it("applies the same even-tie rule to credits and refunds", () => {
    expect(roundCents(-2.5)).toBe(-2);
    expect(roundCents(-1.5)).toBe(-2);
    expect(roundCents(-12.51)).toBe(-13);
  });
});

